package com.insurance.claim.controller;
import com.insurance.claim.service.ClaimService; import com.insurance.claim.saga.SettlementSagaService; import org.springframework.http.ResponseEntity; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.UUID;
@RestController @RequestMapping("/api/v1/claims") public class SettlementController { private final ClaimService claimService; private final SettlementSagaService settlementSagaService; public SettlementController(ClaimService claimService,SettlementSagaService settlementSagaService){this.claimService=claimService;this.settlementSagaService=settlementSagaService;} @PostMapping("/{claimId}/approve") @PreAuthorize("hasAnyRole('ADJUSTER','ADMIN')") public ResponseEntity<ApprovalResponse> approve(@PathVariable UUID claimId){UUID sagaId=claimService.approveClaim(claimId);settlementSagaService.process(sagaId);return ResponseEntity.accepted().body(new ApprovalResponse(claimId,sagaId,"SETTLEMENT_STARTED"));} public record ApprovalResponse(UUID claimId,UUID sagaId,String status){} }
